    "name": "Bring My Spark Back – The Amethyst Crazy Lace Agate Pendant",
    "tagline": "Do you miss when your days were nothing but fun and free? When laughter came easy? Then life happened. The joy left. Boredom settled in. And exhaustion became a companion that never leaves. Maybe you’ve forgotten how to relax, how to find joy, how to have fun.",
    "material": "Pendant made with natural crystal materials selected for a tactile, everyday piece. Tags: Agate, Amethyst, Crazy Lace Agate, jewelry_all_collections, Necklace, necklace_coll, new arrivals.",
    "energy": [
      "Do you miss when your days were nothing but fun and free? When laughter came easy? Then life happened. The joy left. Boredom settled in. And exhaustion became a companion that never leaves. Maybe you’ve forgotten how to relax, how to find joy, how to have fun.",
      "If you feel stuck in the middle, keep reading, because this one was made for you.",
      "For many, Amethyst Crazy Lace Agate feels like a miracle. Not for its strength, but because it's known for delivering on two promises that normally cancel each other out… A rare pairing, and a striking one to hold.",
      "High-grade Amethyst is the quiet one. It slows you down, pulls you inward, and settles the noise. Crazy Lace Agate is light and bright. Known as the Laughter Stone, it’s said to lift any mood and loosen a person up. Most crystals provide one feeling. This combination may be your spark of joy and your sense of serenity, said to give both back at once when you feel wound up and flat at the same time.",
      "Together, this pairing carries a specific gift. It seeks to bring play back to the person who became all responsibility. It’s believed to be the remedy to the thing you don’t admit out loud: I used to be more fun, and I miss it. Ready to turn the light within back on again?",
      "Amethyst is long known as a protective stone, and here that shows up quietly. For the person who feels everything, it's said to help you tell which feelings are truly yours and which you picked up off the room, so you can be the steady one when someone else is falling apart and keep your footing when everything is shifting at once.",
      "Amethyst is usually sold as a sleep stone. Paired with Crazy Lace Agate, what's said to happen once you're asleep is even better. Vivid dreams and easier dream recall. Perhaps even lucid dreaming. And turning rest into another kind of waking life.",
      "Let this be the stone that brings the light back and makes life easy again."
    ],
