      "This stone has a remarkable origin story. Deep underground, it was shattered into pieces by forces far stronger than itself. Then, over millions of years, the earth pressed those pieces back together. Whole again, and stronger than before. The swirling patterns you see aren’t just beautiful. They’re the seams, the exact lines where it came back together. Every one is proof it broke, and proof it healed. Just like you.",
