      "The Natural Energy Lamp is the best way to introduce an abundance of healing energy into your room. Its light is bright but soothing—perfect for late-night bursts of productivity. Crucially, the eight raw stones’ energy works regardless of whether the light is switched on or off.",
      "Stop negative self-talk in its tracks with Rose Quartz . Welcome in endless love instead. It brings compassion, peace, and generosity, encouraging you to be kind wherever you go. Even to yourself. Red Agate is a fantastic gemstone for balance. It grounds your energy and reignites the passion in your love life or work life. Traditionally linked to vitality and sensual energy, Red Agate brings the yin and yang energies into harmony. Apatite helps you remain calm in times of frustration. It soothes irritability and brings clarity in times of confusion. A creative stone, Apatite helps you overcome sorrow, apathy, or anger in inventive ways.",
