      "Green Aventurine is a stone of soft healing energy. It’s one of the best break-up crystals, holding your hand as your heart heals. It inspires confidence and courage, even when all the odds are stacked against you. Black Tourmaline is a protective powerhouse. It soaks up negative energy and keeps your aura cozy and safe. Activate the base chakra, center your energy, and cleanse your mind, body and spirit.",
      "Get the Natural Energy Lamp to refresh your room and revitalize your mind, body and soul.",
      "How to use this lamp",
      "The lamp comes with a USB cable: attach an adaptor and connect it to a power outlet and you’re good to go! Place it on a desk or table in your bedroom and switch it on to instantly create a calm atmosphere. The crystals’ energy works constantly in the background, so even if it was only used for decoration, you’d still reap the rewards. However, you can also use the natural stones to accompany you during meditation, or to create crystal grids or intention-setting ceremonies.",
